func pieces(_ transfers: [Transfer]) -> ([String], [Int]) {
  let posted = transfers.filter { t in t.posted == true }
  let recipients = posted.map { t in t.recipient }
  let amounts = posted.compactMap { t in Int(t.amountText) }
  return (recipients, amounts)
}

